eventScript.func:
const showStatusHTML = (status) => {
  const statusMap = {
    Draft: "draft_status",
    Created: "created_status",
    Cancelled: "cancelled_status",
    Issued: "issued_status",
    Completed: "completed_status",
    "Fully Posted": "fullyposted_status",
    Processing: "processing_status",
  };
  if (statusMap[status]) {
    this.display([statusMap[status]]);
  }
};

const EDIT_DISABLED_FIELDS = [
  "issuing_operation_faci",
  "stock_movement_no",
  "stock_movement_no_type",
  "item_id",
  "item_name",
  "item_desc",
  "item_qty",
  "item_uom",
  "issued_by",
  "project_id",
  "batch_no",
  "manufacturing_date",
  "expired_date",
  "storage_location_id",
  "location_id",
  "inventory_category",
  "item_assembly_date",
  "reference_documents",
  "net_weight",
  "gross_weight",
  "remarks",
  "remarks_2",
  "remarks_3",
];

// Batch No is typed only under Manual Input; a System Settings batch is generated
// on completion. Any batch item takes the dates.
const showBatchFields = async (itemId) => {
  if (!itemId) return;

  const res = await db
    .collection("item")
    .where({ id: itemId })
    .field("item_batch_management,batch_number_genaration,serial_number_management,stock_control")
    .get();
  const item = res.data?.[0];
  // IA output split (scratchpad/iasc os_main): the rows, the switch and the columns for this item
  this.triggerEvent("os_main", { osOp: "MOUNT", item: item || null });
  // -- end output split --
  if (item?.item_batch_management !== 1) return;

  const fields = ["manufacturing_date", "expired_date"];
  if (item.batch_number_genaration !== "According To System Settings") {
    fields.push("batch_no");
  }
  this.display(fields);
};

// Past Draft the fields are read-only, so only the ones holding a value are shown.
const showFilledBatchFields = () => {
  // IA output split (scratchpad/iasc os_main): a read-only view shows the split's rows
  this.triggerEvent("os_main", { osOp: "VIEW" });
  // -- end output split --
  const filled = ["batch_no", "manufacturing_date", "expired_date"].filter(
    (field) => this.getValue(field)
  );
  if (filled.length) this.display(filled);
};

// Locking the components table is not enough on its own: this.disabled leaves the
// toolbar's Add / Batch Add buttons and the per-row delete action clickable, so
// they are taken out of the DOM as well. Same approach as MSI's editDisabledField.
const lockComponentsTable = () => {
  this.disabled(["stock_movement"], true);

  setTimeout(() => {
    const styleId = "ia-hide-row-actions";
    if (!document.getElementById(styleId)) {
      const style = document.createElement("style");
      style.id = styleId;
      style.textContent = `
        .fm-virtual-table__row-cell .scope-action { display: none !important; }
        .fm-virtual-table__row-cell .scope-index { display: flex !important; }
      `;
      document.head.appendChild(style);
    }

    const toolbarButtons = document.querySelectorAll(
      ".el-row .el-col.el-col-12.el-col-xs-24 .el-button.el-button--primary.el-button--default.is-link"
    );
    toolbarButtons.forEach((button) => {
      button.style.display = "none";
    });
  }, 500);
};

// Mirrors MSI: a plant-level login can only issue from its own plant, so the
// field is fixed to it and locked; an org-level login picks one.
const setPlant = (organizationId, pageStatus) => {
  const currentDept = this.getVarSystem("deptIds").split(",")[0];
  const isSameDept = currentDept === organizationId;
  const isNew = pageStatus === "Add" || pageStatus === "Clone";

  this.disabled(["issuing_operation_faci"], !isSameDept);

  if (isNew && !isSameDept) {
    this.setData({ issuing_operation_faci: currentDept });
    this.disabled(["stock_movement"], false);
    // Reuse the plant handler so the storage location and bin defaults are
    // resolved in exactly one place.
    this.triggerEvent("onChange_Plant", { value: currentDept });
  } else if (isNew && isSameDept) {
    this.disabled(["stock_movement"], true);
  }

  return currentDept;
};

// IA V2: an Item Assembly a background job holds stays Processing (read-only, no save or post button) until the job ends;
// opening it follows the job: STATUS, and a worker kick every 15 s (the completion worker for a completion, the revert worker
// for a revert). A failed background job is reported once per browser. With both switches false (or a workflow id not set)
// nothing here calls a workflow or touches browser storage.
const IA_BG_WF = {
  SUBMIT: "2112141238600376321", // IA_V2_SUBMIT
  WORKER: "2112141277456408577", // IA_V2_WORKER
  REVERT_SUBMIT: "2112141384234999809", // IA_REVERT_V2_SUBMIT
  REVERT_WORKER: "2112141417890095105", // IA_REVERT_V2_WORKER
};
// the Completed buttons' switch and the list's Revert switch
const IA_BG_ENABLED = true;
const IA_BG_REVERT_ENABLED = true;
const IA_BG_POLL_MS = 3000;
const IA_BG_KICK_MS = 15000;
const IA_BG_WAIT_MS = 420000;

const iaBgId = (v) => /^[1-9][0-9]{0,19}$/.test(String(v || "").trim());
const iaBgOn = () => IA_BG_ENABLED === true && iaBgId(IA_BG_WF.SUBMIT) && iaBgId(IA_BG_WF.WORKER);
const iaBgRevertOn = () => IA_BG_REVERT_ENABLED === true && iaBgId(IA_BG_WF.REVERT_SUBMIT) && iaBgId(IA_BG_WF.REVERT_WORKER);
const iaBgText = (v) => String(v === undefined || v === null ? "" : v).trim();

const iaBgRun = (id, params) =>
  new Promise((resolve, reject) => {
    const p = this.runWorkflow(
      id,
      params,
      (res) => resolve(res),
      (err) => reject(err),
    );
    if (p && typeof p.then === "function") p.then((res) => resolve(res), (err) => reject(err));
  });

// STATUS answers the assembly's latest job of either command; its action (DIRECT / REVERT) says which worker moves it
const iaBgStatus = async (iaId) => {
  try {
    const res = iaBgOn()
      ? await iaBgRun(IA_BG_WF.SUBMIT, { operation: "STATUS", saveAs: "Completed", pageStatus: "Edit", ia_id: String(iaId),
        idempotency_key: "", source: "FORM", form: {} })
      : await iaBgRun(IA_BG_WF.REVERT_SUBMIT, { operation: "STATUS", ia_id: String(iaId), idempotency_key: "", source: "FORM",
        min_picks: "", form: {} });
    return (res && res.data) || null;
  } catch (error) {
    console.error("Background job: status check failed", error);
    return null;
  }
};

const iaBgIsRevert = (st) => iaBgText(st && st.action) === "REVERT" || iaBgText(st && st.command) === "REVERT_IA";

const iaBgKick = (workerId, jobId) => {
  if (!workerId) return;
  try {
    const p = this.runWorkflow(
      workerId,
      { job_id: String(jobId) },
      () => {},
      (error) => console.error("Background job: worker start failed", error),
    );
    if (p && typeof p.catch === "function") p.catch(() => {});
  } catch (error) {
    console.error("Background job: worker could not be started", error);
  }
};

// true when this browser already showed the job (and marks it shown)
const iaFailedSeen = (jobId) => {
  let seen = false;
  try {
    const key = "ia_v2_failed_seen_" + jobId;
    seen = localStorage.getItem(key) === "1";
    localStorage.setItem(key, "1");
  } catch (e) {}
  return seen;
};

const iaBgAlert = (message, title, type) => this.$alert(message, title, { confirmButtonText: "OK", type: type }).catch(() => {});

const iaFollowBackground = async (iaId, name, jobOnRecord) => {
  const refreshList = () => {
    if (this.parentGenerateForm) this.parentGenerateForm.refresh();
  };
  const deadline = Date.now() + IA_BG_WAIT_MS;
  let kickedAt = 0;
  let st = await iaBgStatus(iaId);
  for (;;) {
    // no job holds it (any more): stop following - the assembly on screen may be out of date
    if (st && (st.job_status === "NONE" || (iaBgText(st.terminal) === "YES" && !st.job_id))) {
      // a new assembly whose completion stopped before it was linked to its job is released only when that job is worked
      if (/^[0-9]{1,20}$/.test(jobOnRecord) && iaBgOn()) iaBgKick(IA_BG_WF.WORKER, jobOnRecord);
      refreshList();
      this.$message.warning(name + " is not being processed in the background any more. Close it and open it again to see its current state.");
      return;
    }
    if (st && st.job_id) {
      const revert = iaBgIsRevert(st);
      const verb = revert ? "reverted" : "completed";
      const js = iaBgText(st.job_status);
      if (js === "COMPLETED") {
        this.$message.success(name + (revert ? " has been reverted to Draft." : " has been completed.") + " Reopen it to see the result.");
        refreshList();
        return;
      }
      if (js === "FAILED" || js === "CANCELLED") {
        refreshList();
        if (iaFailedSeen(st.job_id)) return;
        const reason = iaBgText(st.error_message || st.error_code || "No reason was given.");
        await iaBgAlert(reason + (/[.!?]$/.test(reason) ? "" : ".") + " Reopen it to continue.", name + " was not " + verb, "error");
        return;
      }
      if (js === "REQUIRES_REVIEW") {
        await iaBgAlert(
          "It stopped part-way through and needs a review before it can be changed. Please contact support." +
            (st.error_message ? " (" + st.error_message + ")" : ""),
          name + " needs a review",
          "warning",
        );
        return;
      }
      // a job waiting out a retry backoff, a stock-lock wait or a parked second phase moves only when kicked again
      if (!kickedAt || Date.now() - kickedAt >= IA_BG_KICK_MS) {
        if (!kickedAt) this.$message.info(name + " is being " + verb + " in the background. It is read-only until that finishes.");
        kickedAt = Date.now();
        iaBgKick(revert ? (iaBgRevertOn() ? IA_BG_WF.REVERT_WORKER : "") : iaBgOn() ? IA_BG_WF.WORKER : "", st.job_id);
      }
    }
    if (Date.now() >= deadline) {
      this.$message.info(name + " is still being processed in the background. Reopen it later.");
      return;
    }
    await new Promise((resolve) => setTimeout(resolve, IA_BG_POLL_MS));
    st = await iaBgStatus(iaId);
  }
};

// an assembly a background job once held (ia_v2_job_id) and released: a failure is shown once per browser; a job with nothing
// to show is not asked about again in this browser
const iaShowLastFailure = async (iaId, jobId, name) => {
  try {
    if (localStorage.getItem("ia_v2_failed_seen_" + jobId) === "1") return;
  } catch (e) {
    return;
  }
  const st = await iaBgStatus(iaId);
  if (!st || !st.job_id) return;
  const js = iaBgText(st.job_status);
  if (["FAILED", "CANCELLED", "COMPLETED"].indexOf(js) < 0) return;
  const shown = iaFailedSeen(st.job_id);
  if (String(st.job_id) !== String(jobId)) iaFailedSeen(jobId);
  if (shown || js === "COMPLETED") return;
  const reason = iaBgText(st.error_message || st.error_code || "No reason was given.");
  this.$message.warning(name + ": its last background " + (iaBgIsRevert(st) ? "revert" : "completion") + " failed - " + reason);
};

const iaBackgroundView = (pageStatus, status) => {
  if (pageStatus !== "Edit" && pageStatus !== "View") return;
  const on = iaBgOn() || iaBgRevertOn();
  if (status !== "Processing" && (!on || (status !== "Draft" && status !== "Created" && status !== "Completed"))) return;
  const jobOnRecord = iaBgText(this.getValue("ia_v2_job_id"));
  if (status !== "Processing" && !/^[0-9]{1,20}$/.test(jobOnRecord)) return;
  const iaId = iaBgText(this.getValue("id"));
  const name = ("Item Assembly " + iaBgText(this.getValue("stock_movement_no"))).trim();
  if (status === "Processing") {
    if (!on) {
      this.$message.warning(name + " is being processed in the background. It is read-only until that finishes.");
      return;
    }
    iaFollowBackground(iaId, name, jobOnRecord);
    return;
  }
  if (iaBgId(iaId)) iaShowLastFailure(iaId, jobOnRecord, name);
};

// Small Cycle (scratchpad/iasc): after the v36 mounted work, the event sc_main (op MOUNT) shows the Small Cycle widgets for this
// page and status, reads the linked line's figures and, on a Sales Order line entry, prepares the components. Opening an
// Item Assembly never rebuilds its lines.
const SC_ENABLED = true;
const SC_WF_PROJECTION = "2112448183267332097"; // SO_IA_PROJECTION
const SC_WF_RELINK = "2112448260018900994"; // IA_SC_RELINK
const scMount = (pageStatus, status) => {
  if (!(SC_ENABLED === true && /^[1-9][0-9]{0,19}$/.test(SC_WF_PROJECTION) && /^[1-9][0-9]{0,19}$/.test(SC_WF_RELINK))) return;
  this.triggerEvent("sc_main", { scOp: "MOUNT", pageStatus: pageStatus, status: status });
};
// -- end Small Cycle --
(async () => {
  try {
    let pageStatus = "";

    if (this.isAdd) pageStatus = "Add";
    else if (this.isEdit) pageStatus = "Edit";
    else if (this.isView) pageStatus = "View";
    else if (this.isCopy) pageStatus = "Clone";
    else throw new Error("Invalid page state");

    let organizationId = this.getVarGlobal("deptParentId");
    if (organizationId === "0") {
      organizationId = this.getVarSystem("deptIds").split(",")[0];
    }

    this.setData({ page_status: pageStatus });
    const status = this.getValue("item_assembly_status");

    // Assemblies saved before the field existed were all received Unrestricted.
    if (pageStatus !== "Add" && !this.getValue("inventory_category")) {
      this.setData({ inventory_category: "Unrestricted" });
    }

    switch (pageStatus) {
      case "Add":
      case "Clone":
        this.setData({
          organization_id: organizationId,
          issued_by: this.getVarGlobal("nickname"),
          item_assembly_date: new Date().toISOString().split("T")[0],
        });
        this.display([
          "draft_status",
          "button_draft",
          "button_completed",
          "comp_post_button",
        ]);

        setPlant(organizationId, pageStatus);

        if (pageStatus === "Clone") {
          // A batch belongs to one assembly run, so a clone starts without one.
          this.setData({
            batch_no: "",
            manufacturing_date: null,
            expired_date: null,
          });
          await showBatchFields(this.getValue("item_id"));
        }
        break;

      case "Edit":
        showStatusHTML(status);

        // A draft is still being written, so the header stays editable; every
        // later status locks it. Same rule as Handling Unit and Misc Issue.
        if (status !== "Draft" && status !== "Created") {
          this.disabled(EDIT_DISABLED_FIELDS, true);
        }

        if (status === "Completed") {
          this.display(["button_post"]);
          lockComponentsTable();
        } else if (status === "Draft") {
          this.display([
            "button_draft",
            "button_completed",
            "comp_post_button",
          ]);
        } else if (status === "Created") {
          // RES-01 Created (BA, 10-22): saved and reserving; an edit is saved as Created again (it never goes back to Draft)
          this.display(["button_created", "button_completed", "comp_post_button"]);
        } else if (status === "Cancelled") {
          // RES-01 Cancel (user 10-22): cancelled, its reservation released: read-only, no button
          lockComponentsTable();
        } else if (status === "Processing") {
          // a background job holds it: read-only, no save or post button
          this.hide(["button_draft", "button_completed", "comp_post_button", "button_post"]);
          lockComponentsTable();
        } else {
          // Fully Posted and anything else past Draft: the stock has already
          // moved, so the components must not be editable either.
          this.display(["button_completed", "comp_post_button"]);
          lockComponentsTable();
        }

        if (status === "Draft" || status === "Created") await showBatchFields(this.getValue("item_id"));
        else showFilledBatchFields();
        break;

      case "View":
        showStatusHTML(status);
        this.disabled(EDIT_DISABLED_FIELDS, true);
        lockComponentsTable();
        showFilledBatchFields();
        break;
    }

    iaBackgroundView(pageStatus, status);
    scMount(pageStatus, status);
    this.triggerEvent("tr_main", { trOp: "MOUNT", pageStatus: pageStatus, status: status });
  } catch (error) {
    console.error(error);
    this.$message.error(error.message || "An error occurred");
  }
})();

setTimeout(async () => {
  if (!this.isAdd && !this.isCopy) return;

  const maxRetries = 10;
  const interval = 500;
  for (let i = 0; i < maxRetries; i++) {
    const op = await this.onDropdownVisible("stock_movement_no_type", true);
    if (op != null) break;
    await new Promise((resolve) => setTimeout(resolve, interval));
  }

  function getDefaultItem(arr) {
    return arr?.find((item) => item?.item?.is_default === 1);
  }

  const params = this.getComponent("stock_movement_no");
  const { options } = params;
  const optionsData = this.getOptionData("stock_movement_no_type") || [];
  const defaultData = getDefaultItem(optionsData);

  if (options?.canManualInput) {
    if (!optionsData.some((option) => option.value === -9999)) {
      this.setOptionData("stock_movement_no_type", [
        { label: "Manual Input", value: -9999 },
        ...optionsData,
      ]);
    }
    this.setData({
      stock_movement_no_type: defaultData ? defaultData.value : -9999,
    });
  } else if (defaultData) {
    this.setData({ stock_movement_no_type: defaultData.value });
  }
}, 200);

// onFormChange - Small Cycle (scratchpad/iasc): RES-01 MIN-06 (BA 10-22). A Created IA's reservation row says when the form holds
// unsaved changes to what the reservation reads (its figures are the last save's), and drops it when they match again. The newest change
// checks 400 ms later (a burst, e.g. an auto-allocation, costs one check); nothing to do for an IA whose row has no fingerprint.
// RES-01 MIN-06 (BA 10-22): what the reservation reads from the form as one cheap string - each line's id, item, unit and picks (hashed),
// and the plant; Required and the display columns are left out (the open itself fills them)
const RES_DIRTY = " · Unsaved changes: not reserved until saved.";
const resHash = (t) => {
  const text = t === undefined || t === null ? "" : typeof t === "string" ? t : JSON.stringify(t);
  let x = 2166136261;
  for (let i = 0; i < text.length; i++) x = Math.imul(x ^ text.charCodeAt(i), 16777619) >>> 0;
  return x.toString(36);
};
const resFp = (v) => (Array.isArray(v && v.stock_movement) ? v.stock_movement : [])
  .map((l) => [l && l.id, l && l.item_selection, l && l.quantity_uom].map((x) => (x === undefined || x === null ? "" : String(x))).join("|") + "|" +
    resHash(l && l.temp_qty_data) + "|" + resHash(l && l.temp_hu_data))
  .join(";") + "#" + String((v && v.issuing_operation_faci) || "");
(() => {
  const st = this.models["_data"] || {};
  if (!st.res_fp) return;
  const seq = (Number(st.res_seq) || 0) + 1;
  this.models["_data"] = Object.assign({}, st, { res_seq: seq });
  setTimeout(() => {
    const now = this.models["_data"] || {};
    if (now.res_seq !== seq || !now.res_fp) return;
    const dirty = resFp(this.getValues()) !== now.res_fp;
    if (dirty === (now.res_dirty === true)) return;
    this.models["_data"] = Object.assign({}, now, { res_dirty: dirty });
    this.setData({ res_summary: String(now.res_row || "") + (dirty ? RES_DIRTY : "") });
  }, 400);
})();

options.func:
// Small Cycle (scratchpad/iasc): RES-01 - this IA's own holds (its Allocated on_reserved_gd rows, doc_type Item Assembly) are its
// own stock: its auto-allocation and its Transfer Stock picker add them back to the free stock they read (the hold moved them to
// Reserved). Another document's holds never. Only a stored IA that reserves (page Edit, a hold status: a clone carries its source's id
// and status, review I2), whatever the switch (it only makes holds, review I4); any other IA: nothing added.
const resOwnId = (v) => {
  const s = (x) => (x === undefined || x === null ? "" : String(x));
  const id = s(v && v.id);
  return v && s(v.page_status) === "Edit" && s(v.material_hold_status) !== "" && /^[0-9]{1,20}$/.test(id) ? id : "";
};
// the form read only when the reservations already read hold an Item Assembly's row (an IA that never reserved keeps v36's calls)
const resOwnIdOf = (rows, values) => ((Array.isArray(rows) ? rows : []).some((r) => r && String(r.doc_type) === "Item Assembly") ? resOwnId(values()) : "");
// the base quantity this IA holds at material + bin + batch from one category (Unrestricted / Blocked)
const resOwnHeld = (rows, iaId, materialId, binId, batchId, category, item) => {
  const s = (v) => String(v && typeof v === "object" && v.dict_key !== undefined ? v.dict_key : v === undefined || v === null ? "" : v);
  if (!/^[0-9]{1,20}$/.test(s(iaId))) return 0;
  let base = 0;
  (Array.isArray(rows) ? rows : []).forEach((r) => {
    if (!r || Number(r.is_deleted) === 1 || s(r.doc_type) !== "Item Assembly" || s(r.doc_id) !== s(iaId) || s(r.status) !== "Allocated" || s(r.handling_unit_id)) return;
    if ((s(r.from_category) || "Unrestricted") !== category || s(r.material_id) !== s(materialId) || s(r.bin_location) !== s(binId) || s(r.batch_id) !== s(batchId)) return;
    const uom = s(r.item_uom);
    const conv = item && uom && uom !== s(item.based_uom) ? (Array.isArray(item.table_uom_conversion) ? item.table_uom_conversion : []).find((c) => s(c && c.alt_uom_id) === uom) : null;
    base += (parseFloat(r.open_qty) || 0) * (conv && parseFloat(conv.base_qty) > 0 ? parseFloat(conv.base_qty) : 1);
  });
  return base;
};
// -- end Small Cycle --
(async () => {
  this.showLoading("Loading inventory data...");
  try {
    const allData = this.getValues();
    const lineItemData = arguments[0]?.row;
    const rowIndex = arguments[0]?.rowIndex;
    const plant_id = allData.issuing_operation_faci;
    const materialId = lineItemData.item_selection;
    const tempQtyData = lineItemData.temp_qty_data;
    const tempHuData = lineItemData.temp_hu_data;
    const quantityUOM = lineItemData.quantity_uom;
    const organizationId = allData.organization_id;

    if (!materialId) return;

    // ============= HELPERS =============

    // Single `in` query instead of N parallel queries — much cheaper at scale.
    const fetchUomData = async (uomIds) => {
      if (!uomIds || uomIds.length === 0) return [];
      try {
        const resUOM = await db
          .collection("unit_of_measurement")
          .filter([
            {
              type: "branch",
              operator: "all",
              children: [
                {
                  prop: "id",
                  operator: "in",
                  value: uomIds,
                },
              ],
            },
          ])
          .get();
        return resUOM.data || [];
      } catch (error) {
        console.error("Error fetching UOM data:", error);
        return [];
      }
    };

    const convertBaseToAlt = (baseQty, itemData, altUOM) => {
      if (
        !baseQty ||
        !Array.isArray(itemData.table_uom_conversion) ||
        itemData.table_uom_conversion.length === 0 ||
        !altUOM
      ) {
        return baseQty || 0;
      }
      const uomConversion = itemData.table_uom_conversion.find(
        (c) => c.alt_uom_id === altUOM,
      );
      if (!uomConversion || !uomConversion.base_qty) return baseQty;
      return (baseQty / uomConversion.base_qty);
    };

    const parseJSON = (str) => {
      if (
        !str ||
        str === "[]" ||
        (typeof str === "string" && str.trim() === "")
      )
        return [];
      try {
        const parsed = JSON.parse(str);
        return Array.isArray(parsed) ? parsed : [];
      } catch {
        return [];
      }
    };

    const filterZeroQuantityRecords = (data, itemData) => {
      return data.filter((record) => {
        if (itemData.serial_number_management === 1) {
          const hasValidSerial =
            record.serial_number && record.serial_number.trim() !== "";
          if (!hasValidSerial) return false;
          return (
            (record.block_qty && record.block_qty > 0) ||
            (record.reserved_qty && record.reserved_qty > 0) ||
            (record.unrestricted_qty && record.unrestricted_qty > 0) ||
            (record.qualityinsp_qty && record.qualityinsp_qty > 0) ||
            (record.intransit_qty && record.intransit_qty > 0) ||
            (record.balance_quantity && record.balance_quantity > 0)
          );
        }
        return (
          (record.block_qty && record.block_qty > 0) ||
          (record.reserved_qty && record.reserved_qty > 0) ||
          (record.unrestricted_qty && record.unrestricted_qty > 0) ||
          (record.qualityinsp_qty && record.qualityinsp_qty > 0) ||
          (record.intransit_qty && record.intransit_qty > 0) ||
          (record.balance_quantity && record.balance_quantity > 0)
        );
      });
    };

    const generateKey = (item, itemData) => {
      if (itemData.serial_number_management === 1) {
        if (itemData.item_batch_management === 1) {
          return `${item.location_id || "no_location"}-${
            item.serial_number || "no_serial"
          }-${item.batch_id || "no_batch"}`;
        }
        return `${item.location_id || "no_location"}-${
          item.serial_number || "no_serial"
        }`;
      }
      if (itemData.item_batch_management === 1) {
        return `${item.location_id || "no_location"}-${
          item.batch_id || "no_batch"
        }`;
      }
      return `${item.location_id || item.balance_id || "no_key"}`;
    };

    const mergeWithTempData = (freshDbData, tempDataArray, itemData) => {
      if (!tempDataArray || tempDataArray.length === 0) {
        return freshDbData;
      }

      const tempDataMap = new Map(
        tempDataArray.map((tempItem) => [
          generateKey(tempItem, itemData),
          tempItem,
        ]),
      );

      // Pre-compute fresh keys once — avoids re-running generateKey N×T times below.
      const freshKeys = freshDbData.map((d) => generateKey(d, itemData));
      const freshKeySet = new Set(freshKeys);

      const mergedData = freshDbData.map((dbItem, i) => {
        const tempItem = tempDataMap.get(freshKeys[i]);

        if (tempItem) {
          return {
            ...dbItem,
            ...tempItem,
            id: dbItem.id,
            balance_id: dbItem.id,
            fm_key: tempItem.fm_key,
            category: tempItem.category,
            sm_quantity: tempItem.sm_quantity,
            remarks: tempItem.remarks || dbItem.remarks,
          };
        }

        return {
          ...dbItem,
          balance_id: dbItem.id,
        };
      });

      tempDataArray.forEach((tempItem) => {
        const key = generateKey(tempItem, itemData);
        if (!freshKeySet.has(key)) {
          mergedData.push({
            ...tempItem,
            balance_id: tempItem.balance_id || tempItem.id,
          });
        }
      });

      return mergedData;
    };

    const mapBalanceData = (itemBalanceData) => {
      return Array.isArray(itemBalanceData)
        ? itemBalanceData.map((item) => {
            const { id, ...itemWithoutId } = item;
            return {
              ...itemWithoutId,
              balance_id: id,
              category: item.category || "Unrestricted",
            };
          })
        : (() => {
            const { id, ...itemWithoutId } = itemBalanceData;
            return {
              ...itemWithoutId,
              balance_id: id,
              category: itemBalanceData.category || "Unrestricted",
            };
          })();
    };

    // Sum HU-bound qty by location/batch for current material — used to subtract
    // from loose item_balance display so the same physical stock isn't pickable both ways
    const buildHuQtyMap = (allHUs, matId, isBatchManaged, huReservedMap) => {
      const huQtyMap = new Map();
      for (const hu of allHUs) {
        const items = (hu.table_hu_items || []).filter(
          (item) => item.is_deleted !== 1 && item.material_id === matId,
        );
        for (const item of items) {
          const locationId = item.location_id || hu.location_id;
          const key = isBatchManaged
            ? `${locationId}-${item.batch_id || "no_batch"}`
            : `${locationId}`;
          // Subtract reserved portion of this HU item: the reserved qty is
          // logically Reserved (via on_reserved_gd overlay), not Unrestricted,
          // so only the unreserved portion sits in item_balance.unrestricted_qty
          // and should be deducted from the loose display.
          const reservedKey = `${hu.id}|${item.batch_id || ""}`;
          const reservedQty =
            (huReservedMap && huReservedMap.get(reservedKey)) || 0;
          const qty = Math.max(
            0,
            (parseFloat(item.quantity) || 0) - reservedQty,
          );
          if (qty <= 0) continue;
          huQtyMap.set(key, (huQtyMap.get(key) || 0) + qty);
        }
      }
      return huQtyMap;
    };

    // Build HU table from pre-fetched HU data. ALLOW_SPLIT: include HUs that contain
    // the current material; filter table_hu_items down to only the matching items
    // (foreign items in the same HU are hidden, not blocking).
    const buildHandlingUnits = (
      allHUs,
      matId,
      tempHuStr,
      itemData,
      altUOM,
      otherLinesHuAllocations,
      huReservedMap,
    ) => {
      // Map for O(1) other-line allocation lookup (preserves first-match behavior of .find())
      const huAllocMap = new Map();
      for (const a of otherLinesHuAllocations) {
        const k = `${a.handling_unit_id}|${a.material_id}|${a.batch_id || ""}`;
        if (!huAllocMap.has(k)) huAllocMap.set(k, a);
      }

      const huTableData = [];

      for (const hu of allHUs) {
        // ALLOW_SPLIT: keep only items matching the current material; skip the
        // HU entirely if it has none.
        const allActiveItems = (hu.table_hu_items || []).filter(
          (item) => item.is_deleted !== 1 && item.material_id === matId,
        );
        if (allActiveItems.length === 0) continue;

        // Header row placeholder — item_quantity updated after items are added
        const headerRow = {
          row_type: "header",
          handling_unit_id: hu.id,
          handling_no: hu.handling_no,
          material_id: "",
          material_name: "",
          storage_location_id: hu.storage_location_id,
          location_id: hu.location_id,
          batch_id: null,
          item_quantity: 0,
          sm_quantity: 0,
          remark: hu.remark || "",
          balance_id: "",
        };
        huTableData.push(headerRow);

        let headerItemTotal = 0;
        for (const huItem of allActiveItems) {
          const rawBaseQty = parseFloat(huItem.quantity) || 0;
          // Partial GD-reservation deduction in base units, matched on HU + batch
          const reservedKey = `${hu.id}|${huItem.batch_id || ""}`;
          const reservedBase = huReservedMap?.get(reservedKey) || 0;
          const baseQty = Math.max(0, rawBaseQty - reservedBase);
          let displayQty = convertBaseToAlt(baseQty, itemData, altUOM);

          const k = `${hu.id}|${huItem.material_id}|${huItem.batch_id || ""}`;
          const otherLineAlloc = huAllocMap.get(k);
          if (otherLineAlloc) {
            displayQty = Math.max(
              0,
              displayQty - (otherLineAlloc.sm_quantity || 0),
            );
          }

          if (displayQty <= 0) continue;

          headerItemTotal += displayQty;
          huTableData.push({
            row_type: "item",
            handling_unit_id: hu.id,
            handling_no: "",
            material_id: huItem.material_id,
            material_name: huItem.material_name,
            storage_location_id: hu.storage_location_id,
            location_id: huItem.location_id || hu.location_id,
            batch_id: huItem.batch_id || null,
            item_quantity: displayQty,
            item_quantity_base: baseQty,
            sm_quantity: 0,
            remark: "",
            balance_id: huItem.balance_id || "",
            expired_date: huItem.expired_date || null,
            manufacturing_date: huItem.manufacturing_date || null,
            create_time: huItem.create_time || hu.create_time,
          });
        }

        headerRow.item_quantity = headerItemTotal;
      }

      // Drop header rows whose items were all fully allocated by other lines
      const huIdsWithItems = new Set(
        huTableData
          .filter((r) => r.row_type === "item")
          .map((r) => r.handling_unit_id),
      );
      const filtered = huTableData.filter(
        (r) => r.row_type === "item" || huIdsWithItems.has(r.handling_unit_id),
      );

      // Restore sm_quantity from existing temp_hu_data on re-open. Map lookup
      // replaces O(T*N) linear scan.
      const parsedTempHu = parseJSON(tempHuStr);
      if (parsedTempHu.length > 0) {
        const filteredItemMap = new Map();
        for (const row of filtered) {
          if (row.row_type !== "item") continue;
          const k = `${row.handling_unit_id}|${row.material_id}|${
            row.batch_id || ""
          }`;
          if (!filteredItemMap.has(k)) filteredItemMap.set(k, row);
        }
        for (const tempItem of parsedTempHu) {
          if (tempItem.row_type !== "item") continue;
          const k = `${tempItem.handling_unit_id}|${tempItem.material_id}|${
            tempItem.batch_id || ""
          }`;
          const match = filteredItemMap.get(k);
          if (match) match.sm_quantity = tempItem.sm_quantity || 0;
        }
      }

      return filtered;
    };

    // Drawer-scoped selectors so we don't collide with same-id tabs on the parent page
    const TAB_SCOPE = `.el-drawer[role="dialog"] .el-tabs__item`;

    const hideTab = (tabName) => {
      const tab = document.querySelector(`${TAB_SCOPE}#tab-${tabName}`);
      if (tab) tab.style.display = "none";
    };

    const showTab = (tabName) => {
      const tab = document.querySelector(`${TAB_SCOPE}#tab-${tabName}`);
      if (tab) {
        tab.style.display = "flex";
        tab.setAttribute("aria-disabled", "false");
        tab.classList.remove("is-disabled");
      }
    };

    const activateTab = (tabName) => {
      const tab = document.querySelector(`${TAB_SCOPE}#tab-${tabName}`);
      if (tab) tab.click();
    };

    // ============= MAIN =============

    // Hide category-from/to + serial column. MSI uses ALLOW_SPLIT — user picks
    // per-item sm_quantity manually; hu_select column is hidden.
    this.hide([
      "sm_item_balance.table_item_balance.category_from",
      "sm_item_balance.table_item_balance.category_to",
      "sm_item_balance.table_item_balance.serial_number",
      "sm_item_balance.table_hu.hu_select",
    ]);

    // Reset tables and clear category default
    this.setData({
      "sm_item_balance.table_item_balance": [],
      "sm_item_balance.table_hu": [],
      "sm_item_balance.table_item_balance.category": undefined,
    });

    let itemData;
    try {
      const itemResponse = await db
        .collection("Item")
        .where({ id: materialId })
        .get();
      itemData = itemResponse.data?.[0];
    } catch (error) {
      console.error("Error fetching item data:", error);
      return;
    }
    if (!itemData) return;
    // a non-stock (labour / overhead) line takes its quantity as typed: nothing to pick
    if (itemData.stock_control === 0 || itemData.stock_control === "0") {
      this.closeDialog("sm_item_balance");
      this.$message.warning(
        `${lineItemData.item_name || itemData.material_name || "This component"} is not stock-controlled: enter its quantity on the line.`,
      );
      return;
    }

    const isBatchManaged = itemData.item_batch_management === 1;
    const isSerial = itemData.serial_number_management === 1;
    const altUoms =
      itemData.table_uom_conversion?.map((data) => data.alt_uom_id) || [];

    const balanceCollection = isSerial
      ? "item_serial_balance"
      : isBatchManaged
        ? "item_batch_balance"
        : "item_balance";

    // Parallelize independent fetches: UOM, GD reservations, all HUs, balance
    // Active GD reservations for this material. Used to:
    //   (a) Subtract HU-bound reservations from the matching HU+batch row in the
    //       handling_unit display (partial deduction, not full exclusion).
    //   (b) Subtract loose-stock reservations (no handling_unit_id) from the
    //       item_balance display so MSI doesn't pick stock already committed to GD.
    const [uomOptions, reservationRes, huRes, balanceRes] = await Promise.all([
      fetchUomData(altUoms),
      db
        .collection("on_reserved_gd")
        .where({
          plant_id: plant_id,
          organization_id: organizationId,
          material_id: materialId,
          is_deleted: 0,
        })
        .get()
        .catch((error) => {
          console.error("Error fetching on_reserved_gd:", error);
          return { data: [] };
        }),
      (async () => {
        // Find HU IDs containing this material via the flat sub-collection.
        // Avoids the 5000-row default cap on `handling_unit` when many HUs exist.
        try {
          const subRes = await db
            .collection("handling_unit_atu7sreg_sub")
            .where({ material_id: materialId, is_deleted: 0 })
            .get();
          const candidateHuIds = [
            ...new Set(
              (subRes.data || [])
                .map((r) => r.handling_unit_id)
                .filter(Boolean),
            ),
          ];
          if (candidateHuIds.length === 0) return { data: [] };
          return await db
            .collection("handling_unit")
            .filter([
              {
                type: "branch",
                operator: "all",
                children: [
                  { prop: "id", operator: "in", value: candidateHuIds },
                  { prop: "plant_id", operator: "equal", value: plant_id },
                  {
                    prop: "organization_id",
                    operator: "equal",
                    value: organizationId,
                  },
                  { prop: "is_deleted", operator: "equal", value: 0 },
                ],
              },
            ])
            .get();
        } catch (error) {
          console.error("Error fetching handling units:", error);
          return { data: [] };
        }
      })(),
      db
        .collection(balanceCollection)
        .where({ material_id: materialId, plant_id: plant_id })
        .get()
        .catch((error) => {
          console.error(`Error fetching ${balanceCollection} data:`, error);
          return { data: [] };
        }),
    ]);

    this.setOptionData([`sm_item_balance.material_uom`], uomOptions);
    this.setData({
      sm_item_balance: {
        material_id: itemData.material_code,
        material_name: itemData.material_name,
        row_index: rowIndex,
        material_uom: quantityUOM,
      },
    });

    // Only Allocated overlays deduct from unrestricted display. Pending records
    // already moved their qty from unrestricted to reserved bucket on
    // item_balance (at SO save), so subtracting them again would double-deduct.
    // Delivered records are excluded implicitly via the open_qty > 0 guard.
    const activeReservations = (reservationRes.data || []).filter(
      (r) => parseFloat(r.open_qty || 0) > 0 && r.status === "Allocated",
    );

    const convertReservedToBase = (qty, item_uom) => {
      if (!item_uom || item_uom === itemData.based_uom) return qty;
      const conv = itemData.table_uom_conversion?.find(
        (c) => c.alt_uom_id === item_uom,
      );
      if (conv && conv.base_qty) return qty * conv.base_qty;
      return qty;
    };

    // huReservedMap key: `${huId}|${batchId}` -> reserved base qty.
    // Allocated reservations bucket-shift unrestricted_qty → reserved_qty on
    // item_balance at write time, so item_balance.unrestricted_qty is already
    // net of loose Allocated reservations — no looseReservedMap needed.
    // huReservedMap is still built for HU partial-reservation deduction in
    // buildHuQtyMap (ALLOW_SPLIT: subtract reserved portion per HU item).
    const huReservedMap = new Map();
    for (const r of activeReservations) {
      if (!r.handling_unit_id) continue;
      const qtyBase = convertReservedToBase(
        parseFloat(r.open_qty || 0),
        r.item_uom,
      );
      const key = `${r.handling_unit_id}|${r.batch_id || ""}`;
      huReservedMap.set(key, (huReservedMap.get(key) || 0) + qtyBase);
    }

    const allHUs = huRes.data || [];

    let looseRowCount = 0;

    // Filter out HU-bound records from temp_qty_data — those belong to table_hu.
    // Final filter drops rows with no issuable stock: only rows with
    // unrestricted_qty > 0 OR block_qty > 0 are kept (Reserved / QI / InTransit
    // categories aren't issuable via MSI).
    const processBalanceData = (itemBalanceData, itemDataLocal) => {
      const mappedData = mapBalanceData(itemBalanceData);
      let finalData = mappedData;

      if (tempQtyData) {
        try {
          const tempArr = JSON.parse(tempQtyData).filter(
            (it) => !it.handling_unit_id,
          );
          finalData = mergeWithTempData(mappedData, tempArr, itemDataLocal);
        } catch (error) {
          console.error("Error parsing temp_qty_data:", error);
        }
      }

      return filterZeroQuantityRecords(finalData, itemDataLocal).filter(
        (r) =>
          (parseFloat(r.unrestricted_qty) || 0) > 0 ||
          (parseFloat(r.block_qty) || 0) > 0,
      );
    };

    // item_balance.unrestricted_qty is already net of all Allocated loose
    // reservations (bucket-shifted to reserved_qty on save), so only the
    // unreserved HU portion needs deducting here to isolate truly-loose stock.
    // Skip serialized items: HU items don't carry serial_number.
    const applyLooseDeduction = (freshDbData) => {
      if (isSerial) return freshDbData;
      const huQtyMap = buildHuQtyMap(
        allHUs,
        materialId,
        isBatchManaged,
        huReservedMap,
      );
      for (const row of freshDbData) {
        const key = isBatchManaged
          ? `${row.location_id}-${row.batch_id || "no_batch"}`
          : `${row.location_id}`;
        const huQty = huQtyMap.get(key) || 0;
        const totalDeduct = huQty;
        if (totalDeduct > 0) {
          row.unrestricted_qty = Math.max(
            0,
            (row.unrestricted_qty || 0) - totalDeduct,
          );
          row.balance_quantity = Math.max(
            0,
            (row.balance_quantity || 0) - totalDeduct,
          );
        }
      }
      // RES-01: this IA's own holds back into the free stock it shows (and out of the reserved)
      if (resOwnId(allData) && !isSerial) {
        for (const row of freshDbData) {
          ["Unrestricted", "Blocked"].forEach((category) => {
            const own = resOwnHeld(activeReservations, resOwnId(allData), row.material_id, row.location_id, row.batch_id, category, itemData);
            if (!(own > 0)) return;
            if (category === "Unrestricted") row.unrestricted_qty = (parseFloat(row.unrestricted_qty) || 0) + own;
            else row.block_qty = (parseFloat(row.block_qty) || 0) + own;
            row.reserved_qty = Math.max(0, (parseFloat(row.reserved_qty) || 0) - own);
          });
        }
      }
      return freshDbData;
    };

    if (isSerial) {
      this.display([
        "sm_item_balance.table_item_balance.serial_number",
        "sm_item_balance.search_serial_number",
        "sm_item_balance.confirm_search",
        "sm_item_balance.reset_search",
      ]);

      if (isBatchManaged) {
        this.display([
          "sm_item_balance.table_item_balance.batch_id",
          "sm_item_balance.table_item_balance.dialog_expired_date",
          "sm_item_balance.table_item_balance.dialog_manufacturing_date",
        ]);
      } else {
        this.hide([
          "sm_item_balance.table_item_balance.batch_id",
          "sm_item_balance.table_item_balance.dialog_expired_date",
          "sm_item_balance.table_item_balance.dialog_manufacturing_date",
        ]);
      }

      const filteredData = processBalanceData(balanceRes.data || [], itemData);
      looseRowCount = filteredData.length;

      this.setData({
        [`sm_item_balance.table_item_balance`]: filteredData,
        [`sm_item_balance.table_item_balance_raw`]:
          JSON.stringify(filteredData),
      });
    } else if (isBatchManaged) {
      this.display([
        "sm_item_balance.table_item_balance.batch_id",
        "sm_item_balance.table_item_balance.dialog_expired_date",
        "sm_item_balance.table_item_balance.dialog_manufacturing_date",
      ]);
      this.hide("sm_item_balance.table_item_balance.serial_number");

      const itemBalanceData = balanceRes.data || [];
      const mappedData = Array.isArray(itemBalanceData)
        ? itemBalanceData.map((item) => {
            const { id, ...itemWithoutId } = item;
            return {
              ...itemWithoutId,
              balance_id: id,
              dialog_expired_date: item.expired_date,
              dialog_manufacturing_date: item.manufacturing_date,
            };
          })
        : (() => {
            const { id, ...itemWithoutId } = itemBalanceData;
            return {
              ...itemWithoutId,
              balance_id: id,
              dialog_expired_date: itemBalanceData.expired_date,
              dialog_manufacturing_date: itemBalanceData.manufacturing_date,
            };
          })();

      const deducted = applyLooseDeduction(mappedData);
      const filteredData = processBalanceData(deducted, itemData);
      looseRowCount = filteredData.length;

      this.setData({
        [`sm_item_balance.table_item_balance`]: filteredData,
      });
    } else {
      this.hide([
        "sm_item_balance.table_item_balance.batch_id",
        "sm_item_balance.table_item_balance.dialog_expired_date",
        "sm_item_balance.table_item_balance.dialog_manufacturing_date",
        "sm_item_balance.table_item_balance.serial_number",
      ]);

      const dbData = balanceRes.data || [];
      const deducted = applyLooseDeduction(dbData);
      const filteredData = processBalanceData(deducted, itemData);
      looseRowCount = filteredData.length;

      this.setData({
        [`sm_item_balance.table_item_balance`]: filteredData,
        [`sm_item_balance.table_item_balance.unit_price`]:
          itemData.purchase_unit_price,
      });
    }

    // ============= HU TABLE =============

    // Other stock_movement lines' HU allocations for same material — to deduct
    const otherLinesHuAllocations = [];
    if (Array.isArray(allData.stock_movement)) {
      allData.stock_movement.forEach((line, idx) => {
        if (idx === rowIndex) return;
        if (line.item_selection !== materialId) return;
        const huStr = line.temp_hu_data;
        if (!huStr || huStr === "[]") return;
        try {
          const parsed = JSON.parse(huStr);
          if (Array.isArray(parsed)) {
            parsed.forEach((alloc) => {
              if (
                alloc.row_type === "item" &&
                parseFloat(alloc.sm_quantity) > 0
              ) {
                otherLinesHuAllocations.push(alloc);
              }
            });
          }
        } catch (e) {
          console.warn(
            `Failed to parse temp_hu_data for stock_movement row ${idx}`,
          );
        }
      });
    }

    const huTableData = buildHandlingUnits(
      allHUs,
      materialId,
      tempHuData,
      itemData,
      quantityUOM,
      otherLinesHuAllocations,
      huReservedMap,
    );

    // Reset both tabs to visible — clears any stale hide from a previous open
    showTab("handling_unit");
    showTab("loose");

    const hasHu = huTableData.length > 0;
    const hasLoose = looseRowCount > 0;

    if (hasHu) {
      await this.setData({ "sm_item_balance.table_hu": huTableData });

      // Batch all header-row disables into a single call — per-row calls froze
      // the UI at scale (~10K rows = 10K sync UI mutations on main thread).
      const disabledPaths = [];
      for (let idx = 0; idx < huTableData.length; idx++) {
        if (huTableData[idx].row_type === "header") {
          disabledPaths.push(`sm_item_balance.table_hu.${idx}.sm_quantity`);
        }
      }
      if (disabledPaths.length > 0) {
        this.disabled(disabledPaths, true);
      }
    }

    if (!hasHu) hideTab("handling_unit");
    if (!hasLoose) hideTab("loose");

    if (hasHu && hasLoose) {
      activateTab("loose");
    } else if (hasHu) {
      activateTab("handling_unit");
    } else if (hasLoose) {
      activateTab("loose");
    }
  } catch (error) {
    console.error("Error in MSI inventory dialog:", error);
  } finally {
    this.hideLoading();
  }
})();

