      const u = ids.length ? await db.collection("unit_of_measurement").field("uom_name")
        .filter([{ type: "branch", operator: "all", children: [{ prop: "id", operator: "in", value: ids }, { prop: "is_deleted", operator: "equal", value: 0 }] }])
