(async () => {
  // one save per click: a second click while this one validates, checks the BOM or saves is refused (the IA V2 handler's form flag,
  // which it clears before it hands a small IA over to this handler)
  const iaClaimDone = () => (this.models["_data"] = { ...this.models["_data"], ia_submitting: 0 });
  if ((this.models["_data"] || {}).ia_submitting === 1) {
    this.$message.warning("Workflow is already in progress. Please wait.");
    return;
  }
  this.models["_data"] = { ...this.models["_data"], ia_submitting: 1 };
  try {
    await this.validate();

    const rawData = this.getValues();
    // sm_item_balance is the stock dialog's model, not a column on the table.
    const { sm_item_balance, ...data } = rawData;
    const pageStatus = data.page_status;

    if (!(await confirmBomVariance(data))) return;

    this.showLoading("Saving Item Assembly as Completed & Posting...");

    let organizationId = this.getVarGlobal("deptParentId");
    if (organizationId === "0") {
      organizationId = this.getVarSystem("deptIds").split(",")[0];
    }

    let workflowResult;

    await this.runWorkflow(
      IA_SAVE_WORKFLOW_ID,
      { allData: data, saveAs: "Completed", pageStatus },
      (res) => {
        workflowResult = res;
      },
      (err) => {
        workflowResult = err;
      },
    );

    if (!workflowResult || !workflowResult.data) {
      this.hideLoading();
      this.$message.error("No response from workflow");
      return;
    }

    const code = workflowResult.data.code;
    if (code && String(code) !== "200") {
      this.hideLoading();
      this.$message.error(
        workflowResult.data.message ||
          workflowResult.data.msg ||
          "Failed to save the Item Assembly",
      );
      return;
    }

    // The save workflow returns the id as an array, the same as the Misc Issue one.
    const savedId = workflowResult.data.id;
    const stockMovementId = Array.isArray(savedId) ? savedId[0] : savedId;

    if (!stockMovementId) {
      console.error("Could not resolve the Item Assembly ID", workflowResult);
      this.$message.warning(
        "Item Assembly completed, but posting could not be started. Please post it from the Item Assembly list.",
      );
      closeDialog();
      return;
    }

    resCloseAfter({ id: stockMovementId }, data);
    await postToAccounting(stockMovementId, organizationId);
  } catch (error) {
    this.hideLoading();
    console.error(error);

    let errorMessage = "";
    if (error && typeof error === "object") {
      errorMessage = findFieldMessage(error) || "An error occurred";
      // findFieldMessage bottoms out at obj.toString(), which is the useless
      // "[object Object]" for a rejected response or a thrown validator.
      if (errorMessage === "[object Object]") {
        errorMessage =
          error.message ||
          error.msg ||
          JSON.stringify(error) ||
          "An error occurred";
      }
    } else {
      errorMessage = error;
    }

    this.$message.error(errorMessage);
  } finally {
    iaClaimDone();
  }
})();

