  const clear = { bom_snapshot_json: "", source_bom_id: "", planned_output_qty: null };
  (v.stock_movement || []).forEach((l, i) => {
    if (scS(l.sc_ref_key)) clear[`stock_movement.${i}.sc_ref_key`] = "";
  });
  await this.setData(clear);
  scStore({ sc_item: value });
  await scSleep(0);
